import Foundation
import Vapor

// Upload processing microservice with quota enforcement
final class UploadService {
    private let storageLimit: Int64 = 104857600 // 100MB per user
    private let processingQueue = DispatchQueue(label: "upload.processing", attributes: .concurrent)
    private var userStorage: [String: UserStorageState] = [:]
    private let stateLock = NSLock()

    struct UserStorageState {
        var currentUsage: Int64
        var pendingUploads: [UUID: PendingUpload]
        var isProcessing: Bool
    }

    struct PendingUpload {
        let id: UUID
        let size: Int64
        let data: Data
        let contentType: String
    }

    func configure(routes: RoutesBuilder) {
        routes.post("upload", ":userId", use: handleUpload)
        routes.get("usage", ":userId", use: getUsage)
    }

    private func getOrCreateState(for userId: String) -> UserStorageState {
        stateLock.lock()
        defer { stateLock.unlock() }
        if let state = userStorage[userId] {
            return state
        }
        let newState = UserStorageState(currentUsage: 0, pendingUploads: [:], isProcessing: false)
        userStorage[userId] = newState
        return newState
    }

    private func updateState(for userId: String, mutator: (inout UserStorageState) -> Void) {
        stateLock.lock()
        if userStorage[userId] == nil {
            userStorage[userId] = UserStorageState(currentUsage: 0, pendingUploads: [:], isProcessing: false)
        }
        mutator(&userStorage[userId]!)
        stateLock.unlock()
    }

    private func handleUpload(req: Request) async throws -> Response {
        guard let userId = req.parameters.get("userId"),
              userId.count <= 64,
              userId.allSatisfy({ $0.isLetter || $0.isNumber || $0 == "-" }) else {
            throw Abort(.badRequest, reason: "Invalid user ID")
        }

        guard let contentType = req.headers.contentType?.serialize(),
              ["image/png", "image/jpeg", "application/pdf"].contains(contentType) else {
            throw Abort(.unsupportedMediaType)
        }

        let body = try await req.body.collect(max: 10_485_760).get() // 10MB max single file
        guard let bodyData = body.getData(at: 0, length: body.readableBytes) else {
            throw Abort(.badRequest)
        }

        let uploadSize = Int64(bodyData.count)
        let uploadId = UUID()

        // Phase 1: Reserve quota atomically
        let reservationResult = reserveQuota(userId: userId, uploadId: uploadId, size: uploadSize)
        guard reservationResult else {
            throw Abort(.payloadTooLarge, reason: "Storage quota exceeded")
        }

        // Phase 2: Validate content asynchronously
        let validationResult = await validateContent(data: bodyData, contentType: contentType, userId: userId)

        guard validationResult.isValid else {
            releaseQuota(userId: userId, uploadId: uploadId)
            throw Abort(.unprocessableEntity, reason: validationResult.reason)
        }

        // Phase 3: Commit the upload
        commitUpload(userId: userId, uploadId: uploadId, size: uploadSize)

        return Response(status: .created, body: .init(string: "{\"id\": \"\(uploadId.uuidString)\"}" ))
    }

    private func reserveQuota(userId: String, uploadId: UUID, size: Int64) -> Bool {
        var success = false
        updateState(for: userId) { state in
            let projectedUsage = state.currentUsage + size + state.pendingUploads.values.reduce(0) { $0 + $1.size }
            if projectedUsage <= self.storageLimit {
                state.pendingUploads[uploadId] = PendingUpload(id: uploadId, size: size, data: Data(), contentType: "")
                success = true
            }
        }
        return success
    }

    private func releaseQuota(userId: String, uploadId: UUID) {
        updateState(for: userId) { state in
            state.pendingUploads.removeValue(forKey: uploadId)
        }
    }

    private func commitUpload(userId: String, uploadId: UUID, size: Int64) {
        updateState(for: userId) { state in
            state.pendingUploads.removeValue(forKey: uploadId)
            state.currentUsage += size
        }
    }

    private func validateContent(data: Data, contentType: String, userId: String) async -> (isValid: Bool, reason: String) {
        // Simulate async content validation (virus scan, format check)
        // This calls back into the state to check processing flag
        let state = getOrCreateState(for: userId)

        // Mark as processing - but note: getOrCreateState returns a COPY
        // The isProcessing flag check is on a stale snapshot
        if state.isProcessing {
            return (false, "Another upload is being processed")
        }

        // Set processing flag
        updateState(for: userId) { state in
            state.isProcessing = true
        }

        // Simulate async validation work
        try? await Task.sleep(nanoseconds: 100_000_000) // 100ms

        let isValid = validateMagicBytes(data: data, contentType: contentType)

        // Clear processing flag
        updateState(for: userId) { state in
            state.isProcessing = false
        }

        return (isValid, isValid ? "" : "Invalid file content")
    }

    private func validateMagicBytes(data: Data, contentType: String) -> Bool {
        guard data.count >= 4 else { return false }
        let header = [UInt8](data.prefix(4))
        switch contentType {
        case "image/png":
            return header[0] == 0x89 && header[1] == 0x50 && header[2] == 0x4E && header[3] == 0x47
        case "image/jpeg":
            return header[0] == 0xFF && header[1] == 0xD8 && header[2] == 0xFF
        case "application/pdf":
            return header[0] == 0x25 && header[1] == 0x50 && header[2] == 0x44 && header[3] == 0x46
        default:
            return false
        }
    }

    private func getUsage(req: Request) async throws -> Response {
        guard let userId = req.parameters.get("userId"),
              userId.count <= 64,
              userId.allSatisfy({ $0.isLetter || $0.isNumber || $0 == "-" }) else {
            throw Abort(.badRequest)
        }
        let state = getOrCreateState(for: userId)
        let json = "{\"usage\": \(state.currentUsage), \"limit\": \(storageLimit)}"
        return Response(status: .ok, body: .init(string: json))
    }
}
